using MVZ2.Vanilla.Enemies;
using MVZ2.Vanilla.Entities;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Modifiers;
using UnityEngine;

namespace MVZ2.GameContent.Buffs.Enemies
{
    public abstract class AIEntityBehaviourBuff : BuffDefinition
    {
        public AIEntityBehaviourBuff(string nsp, string name) : base(nsp, name)
        {
        }
        public override sealed void PostUpdate(Buff buff)
        {
            base.PostUpdate(buff);
            var entity = buff.GetEntity();
            if (entity == null)
                return;
            if (!entity.IsAIFrozen())
            {
                UpdateAI(buff, entity);
            }
            UpdateLogic(buff, entity);
        }
        public virtual void UpdateAI(Buff buff, Entity entity)
        {

        }
        public virtual void UpdateLogic(Buff buff, Entity entity)
        {

        }
    }
}
